import{_ as d,c as e,o,a2 as c}from"./chunks/framework.CP8b5y1j.js";const m=JSON.parse('{"title":"Codex Slash Commands 总结","description":"","frontmatter":{},"headers":[],"relativePath":"src/AI/Codex命令总结.md","filePath":"src/AI/Codex命令总结.md","lastUpdated":null}'),r={name:"src/AI/Codex命令总结.md"};function a(l,t,i,s,h,n){return o(),e("div",null,[...t[0]||(t[0]=[c('<h1 id="codex-slash-commands-总结" tabindex="-1">Codex Slash Commands 总结 <a class="header-anchor" href="#codex-slash-commands-总结" aria-label="Permalink to &quot;Codex Slash Commands 总结&quot;">​</a></h1><p>整理日期：2026-06-08</p><p>这份文档总结的是 Codex 中常见的 <code>/</code> 命令，也就是 slash commands。 例如 <code>/clear</code> 属于 <strong>Codex CLI 终端版</strong>，不是所有界面都支持同一套命令。</p><h2 id="一、cli-中最常用的命令" tabindex="-1">一、CLI 中最常用的命令 <a class="header-anchor" href="#一、cli-中最常用的命令" aria-label="Permalink to &quot;一、CLI 中最常用的命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>/clear</code></td><td>清屏并新开对话</td></tr><tr><td><code>/new</code></td><td>新开对话，但不清屏</td></tr><tr><td><code>/resume</code></td><td>恢复以前的会话</td></tr><tr><td><code>/status</code></td><td>查看当前模型、权限策略、可写目录、上下文或 token 使用情况</td></tr><tr><td><code>/model</code></td><td>切换模型</td></tr><tr><td><code>/plan</code></td><td>进入规划模式，先让 Codex 给出执行方案</td></tr><tr><td><code>/goal</code></td><td>设定持续目标，让 Codex 围绕该目标继续工作</td></tr><tr><td><code>/review</code></td><td>审查当前工作区改动</td></tr><tr><td><code>/diff</code></td><td>查看 Git diff，包括未跟踪文件</td></tr><tr><td><code>/compact</code></td><td>压缩长对话，节省上下文</td></tr><tr><td><code>/permissions</code></td><td>切换自动批准、只读等权限模式</td></tr></tbody></table><h2 id="二、cli-中偏会话控制的命令" tabindex="-1">二、CLI 中偏会话控制的命令 <a class="header-anchor" href="#二、cli-中偏会话控制的命令" aria-label="Permalink to &quot;二、CLI 中偏会话控制的命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>/fork</code></td><td>把当前对话分叉成一个新线程</td></tr><tr><td><code>/side</code></td><td>开一个临时旁支对话，不打乱主线</td></tr><tr><td><code>/btw</code></td><td>与 <code>/side</code> 类似，用于插入一个临时分支话题</td></tr><tr><td><code>/copy</code></td><td>复制最新一条已完成的 Codex 输出</td></tr><tr><td><code>/raw</code></td><td>切换原始滚动输出模式，方便复制终端内容</td></tr><tr><td><code>/ps</code></td><td>查看后台终端任务状态</td></tr><tr><td><code>/stop</code></td><td>停止后台终端任务</td></tr><tr><td><code>/quit</code></td><td>退出 CLI</td></tr><tr><td><code>/exit</code></td><td>退出 CLI</td></tr></tbody></table><h2 id="三、cli-中偏配置和调试的命令" tabindex="-1">三、CLI 中偏配置和调试的命令 <a class="header-anchor" href="#三、cli-中偏配置和调试的命令" aria-label="Permalink to &quot;三、CLI 中偏配置和调试的命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>/fast</code></td><td>开关 Fast 服务层级，不是所有模型都支持</td></tr><tr><td><code>/personality</code></td><td>切换回复风格</td></tr><tr><td><code>/theme</code></td><td>切换终端高亮主题</td></tr><tr><td><code>/statusline</code></td><td>配置底部状态栏显示项</td></tr><tr><td><code>/title</code></td><td>配置终端窗口标题显示项</td></tr><tr><td><code>/vim</code></td><td>切换 Vim 输入模式</td></tr><tr><td><code>/keymap</code></td><td>修改快捷键映射</td></tr><tr><td><code>/debug-config</code></td><td>查看最终生效的配置及其来源</td></tr><tr><td><code>/experimental</code></td><td>开关实验特性</td></tr><tr><td><code>/approve</code></td><td>对最近一次被自动审查拒绝的动作进行一次手动批准重试</td></tr><tr><td><code>/sandbox-add-read-dir</code></td><td>为沙箱额外添加只读目录，Windows 原生 CLI 专用</td></tr></tbody></table><h2 id="四、cli-中偏工具和集成的命令" tabindex="-1">四、CLI 中偏工具和集成的命令 <a class="header-anchor" href="#四、cli-中偏工具和集成的命令" aria-label="Permalink to &quot;四、CLI 中偏工具和集成的命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>/mention</code></td><td>把文件或目录附加到当前对话上下文</td></tr><tr><td><code>/ide</code></td><td>把 IDE 中打开的文件或选区拉入当前上下文</td></tr><tr><td><code>/init</code></td><td>生成 <code>AGENTS.md</code> 模板</td></tr><tr><td><code>/mcp</code></td><td>查看 MCP 工具或服务状态</td></tr><tr><td><code>/apps</code></td><td>浏览并插入 app 或 connectors</td></tr><tr><td><code>/plugins</code></td><td>查看和管理插件</td></tr><tr><td><code>/skills</code></td><td>浏览并使用技能</td></tr><tr><td><code>/hooks</code></td><td>查看和管理生命周期 hooks</td></tr><tr><td><code>/agent</code></td><td>切换到某个 subagent 线程</td></tr><tr><td><code>/memories</code></td><td>管理 memory 的使用和生成</td></tr><tr><td><code>/feedback</code></td><td>提交反馈，可附日志</td></tr><tr><td><code>/logout</code></td><td>退出登录</td></tr></tbody></table><h2 id="五、ide-扩展中常见命令" tabindex="-1">五、IDE 扩展中常见命令 <a class="header-anchor" href="#五、ide-扩展中常见命令" aria-label="Permalink to &quot;五、IDE 扩展中常见命令&quot;">​</a></h2><p>IDE 扩展里的命令集和 CLI 不完全一样，常见的有：</p><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>/auto-context</code></td><td>自动带上最近文件和 IDE 上下文</td></tr><tr><td><code>/cloud</code></td><td>切换到云端执行</td></tr><tr><td><code>/cloud-environment</code></td><td>选择云端环境</td></tr><tr><td><code>/local</code></td><td>切回本地执行</td></tr><tr><td><code>/review</code></td><td>代码审查模式</td></tr><tr><td><code>/status</code></td><td>查看 thread ID、上下文用量、速率限制</td></tr><tr><td><code>/feedback</code></td><td>提交反馈</td></tr><tr><td><code>/goal</code></td><td>设置持续目标</td></tr></tbody></table><h2 id="六、codex-app-中常见命令" tabindex="-1">六、Codex App 中常见命令 <a class="header-anchor" href="#六、codex-app-中常见命令" aria-label="Permalink to &quot;六、Codex App 中常见命令&quot;">​</a></h2><p>Codex App 里常见的命令更偏任务和状态管理：</p><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>/plan</code></td><td>切换到计划模式</td></tr><tr><td><code>/goal</code></td><td>设置持续目标</td></tr><tr><td><code>/review</code></td><td>代码审查模式</td></tr><tr><td><code>/status</code></td><td>查看线程和上下文状态</td></tr><tr><td><code>/mcp</code></td><td>查看 MCP 连接状态</td></tr><tr><td><code>/feedback</code></td><td>提交反馈</td></tr></tbody></table><h2 id="七、使用时需要注意" tabindex="-1">七、使用时需要注意 <a class="header-anchor" href="#七、使用时需要注意" aria-label="Permalink to &quot;七、使用时需要注意&quot;">​</a></h2><ul><li>命令是否可用，和你所在的界面有关，比如 <code>CLI</code>、<code>IDE 扩展</code>、<code>Codex App</code>。</li><li>同名命令在不同界面里，显示的信息和行为可能略有区别。</li><li>某些命令受模型、权限模式、实验特性或功能开关影响，不一定每个用户都能看到。</li><li><code>/clear</code> 是 CLI 里的命令，不应默认认为在 App 或 IDE 中也存在。</li></ul><h2 id="八、建议优先记住的-15-个命令" tabindex="-1">八、建议优先记住的 15 个命令 <a class="header-anchor" href="#八、建议优先记住的-15-个命令" aria-label="Permalink to &quot;八、建议优先记住的 15 个命令&quot;">​</a></h2><p>如果你主要在 CLI 里用 Codex，优先记这几个：</p><ol><li><code>/clear</code></li><li><code>/new</code></li><li><code>/resume</code></li><li><code>/status</code></li><li><code>/model</code></li><li><code>/plan</code></li><li><code>/goal</code></li><li><code>/review</code></li><li><code>/diff</code></li><li><code>/compact</code></li><li><code>/permissions</code></li><li><code>/mention</code></li><li><code>/mcp</code></li><li><code>/plugins</code></li><li><code>/init</code></li></ol><h2 id="官方文档" tabindex="-1">官方文档 <a class="header-anchor" href="#官方文档" aria-label="Permalink to &quot;官方文档&quot;">​</a></h2><ul><li>CLI slash commands: <a href="https://developers.openai.com/codex/cli/slash-commands" target="_blank" rel="noreferrer">https://developers.openai.com/codex/cli/slash-commands</a></li><li>IDE slash commands: <a href="https://developers.openai.com/codex/ide/slash-commands" target="_blank" rel="noreferrer">https://developers.openai.com/codex/ide/slash-commands</a></li><li>Codex App commands: <a href="https://developers.openai.com/codex/app/commands" target="_blank" rel="noreferrer">https://developers.openai.com/codex/app/commands</a></li></ul>',24)])])}const b=d(r,[["render",a]]);export{m as __pageData,b as default};
